-- Anticheat suspicion reports from the game server (append-only for the app role, except the review mark).
-- The id is generated by the game server, so a retried report never creates a duplicate. No existing data is changed.
CREATE TABLE anticheat_reports (
 id uuid PRIMARY KEY,
 server_id uuid NOT NULL,
 minecraft_uuid uuid NOT NULL,
 player_name varchar(16) NOT NULL CHECK (player_name ~ '^[A-Za-z0-9_]{1,16}$'),
 check_code varchar(32) NOT NULL CHECK (check_code ~ '^[A-Z_]{2,32}$'),
 level varchar(8) NOT NULL CHECK (level IN ('WATCH','ALERT','CRITICAL')),
 score smallint NOT NULL CHECK (score BETWEEN 0 AND 1000),
 detail varchar(300) NOT NULL,
 dimension varchar(64),
 x integer, y integer, z integer,
 occurred_at timestamptz(3) NOT NULL,
 created_at timestamptz(3) NOT NULL DEFAULT now(),
 reviewed_at timestamptz(3),
 reviewed_by uuid REFERENCES users(id) ON DELETE SET NULL,
 CHECK ((reviewed_at IS NULL) = (reviewed_by IS NULL))
);
CREATE INDEX anticheat_reports_created ON anticheat_reports(created_at DESC, id);
CREATE INDEX anticheat_reports_player ON anticheat_reports(minecraft_uuid, created_at DESC);
CREATE INDEX anticheat_reports_open ON anticheat_reports(created_at DESC) WHERE reviewed_at IS NULL;
GRANT SELECT,INSERT ON anticheat_reports TO anime_app;
GRANT UPDATE (reviewed_at, reviewed_by) ON anticheat_reports TO anime_app;
